[
  {
    "name": "小企鹅波波",
    "description": "主角，一只不会飞的小帝企鹅，梦想参加南极飞行大赛",
    "appearance": "3岁小企鹅，圆滚滚身体，黑白羽毛，头顶一撮翘起的呆毛，大眼睛蓝黑色透亮，翅膀短小",
    "costume": "脖子系一条亮蓝色小围巾",
    "personality": "乐观、勇敢、永不放弃，有点冒失但充满善意"
  },
  {
    "name": "北极熊阿白",
    "description": "波波的好朋友，一只小北极熊",
    "appearance": "3岁小北极熊，圆胖可爱，毛色雪白带轻微奶黄，眼神温柔，耳朵小巧",
    "costume": "戴一顶红色小绒帽",
    "personality": "稳重、细心、富有责任感，是波波的守护者"
  },
  {
    "name": "老信天翁",
    "description": "南极飞行大赛的传奇飞行员",
    "appearance": "年迈信天翁，白色羽毛泛着银色光泽，翅膀巨大，眼神锐利慈祥",
    "costume": "戴一副复古飞行护目镜",
    "personality": "严厉但慈祥，懂得飞翔的真正意义"
  },
  {
    "name": "海豹豆豆",
    "description": "比赛报名处的管理员",
    "appearance": "胖乎乎的小海豹，圆脸，胡须翘起",
    "costume": "穿一件橙色工作背心",
    "personality": "热心、有点唠叨、爱帮忙"
  }
]

[
  {
    "name": "南极小渔村",
    "description": "波波的家，冰雪覆盖的小村庄，简朴温馨",
    "visualStyle": "淡蓝色雪景，木质小屋，柔和晨光，炊烟袅袅，手绘水彩质感"
  },
  {
    "name": "企鹅幼儿园",
    "description": "小企鹅们学习的地方",
    "visualStyle": "明亮温暖，墙上画着雪花和企鹅壁画，窗外能看到冰川"
  },
  {
    "name": "南极飞行大赛报名处",
    "description": "冰山搭建的报名大厅",
    "visualStyle": "冰蓝色调，极光投影在冰墙上，热闹非凡"
  },
  {
    "name": "悬崖边缘",
    "description": "波波尝试飞行的训练地",
    "visualStyle": "悬崖下是浩瀚云海，夕阳余晖，金色光晕"
  },
  {
    "name": "极光下的雪原",
    "description": "三人踏上冒险之路的开阔雪原",
    "visualStyle": "紫色绿色极光漫天飞舞，星空璀璨，雪原反射极光"
  }
]

{
  "scenes": [
    {
      "location": "南极小渔村·清晨",
      "time": "清晨",
      "characters": [
        "小企鹅波波"
      ],
      "action": "波波从冰屋小床上醒来，看见窗外其他企鹅在天空飞翔，眼中充满向往。",
      "dialogue": "波波：（看着窗外）今天，南极飞行大赛开始报名啦！",
      "mood": "温馨、期待"
    },
    {
      "location": "企鹅幼儿园",
      "time": "上午",
      "characters": [
        "小企鹅波波",
        "北极熊阿白"
      ],
      "action": "波波在幼儿园心不在焉地练习扑翅膀，却一次次摔倒。阿白走过来扶起他。",
      "dialogue": "波波：我为什么飞不起来呢？阿白：别着急，我们一起去报名看看吧！",
      "mood": "沮丧、温暖"
    },
    {
      "location": "南极小渔村·小路",
      "time": "上午",
      "characters": [
        "小企鹅波波",
        "北极熊阿白"
      ],
      "action": "两人踏上旅程，穿过雪地村庄，村庄企鹅们好奇地看着这只北极熊。",
      "dialogue": "波波：看！他们都在看我！阿白：那是他们觉得我帅气呀！",
      "mood": "轻快、童趣"
    },
    {
      "location": "悬崖边缘",
      "time": "午后",
      "characters": [
        "小企鹅波波",
        "北极熊阿白"
      ],
      "action": "波波来到悬崖边，鼓起勇气张开翅膀跳下，却直接坠落。",
      "dialogue": "波波：我一定会飞起来的！（摔下）哎呀！",
      "mood": "紧张、心疼"
    },
    {
      "location": "极光下的雪原",
      "time": "黄昏",
      "characters": [
        "小企鹅波波",
        "北极熊阿白"
      ],
      "action": "两人互相搀扶，极光点亮夜空，他们看见远处飞行大赛的灯光，决定继续前进。",
      "dialogue": "阿白：你看，极光在为我们指路呢！波波：走，我们出发！",
      "mood": "希望、励志"
    }
  ]
}
